/** Synthetic cases only. The committed oracle is captured from aeb5ce0, never regenerated by tests. */
export async function evaluateFormCase(test:any,api:any):Promise<unknown> {
  try {
    const { definition, answers }=test
    if(test.op==='draft')return api.builder.validateSurveyDraft('FORM',definition,true)
    if(test.op==='dry')return api.final.dryRunSurveyForm(definition,answers)
    if(test.op==='legacy')return api.final.validateSurveyUnitAnswers({kind:'FORM',instrumentKey:'form',sourceDigest:'legacy',displayDefinition:definition},answers)
    if(test.op==='import') {
      const preview=api.bulk.previewBulk(test.input,'FORM',definition.schemaVersion)
      return {preview,...(preview.ok?{applied:api.bulk.applyBulk('FORM',definition,test.input,preview.digest)}:{})}
    }
    const unit=api.publication.compileFrozenResearchUnit({id:'draft',instrumentKey:'form',kind:'FORM',title:'Fixture',revision:1,definition})
    const snapshot={schemaVersion:1,purpose:'RESEARCH_ONLY',projectId:'synthetic',waveId:'wave',collectionMode:'LINKED_WAVES',consentVersion:1,linkageNoticeConfirmed:true,consentDigest:'consent',runtimeStatus:'SURVEY_FINAL_V1',units:[unit]}
    return {unit,result:api.final.computeSurveyFinal(snapshot,{form:answers})}
  } catch(error) {
    const e=error as {name:string;message:string;path?:string;issues?:unknown}
    return {error:{name:e.name,message:e.message,...(e.path===undefined?{}:{path:e.path}),...(e.issues===undefined?{}:{issues:e.issues})}}
  }
}
